public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the array has only one element, return a list containing only that element
    if (nums.length == 1) {
        permutations.add(Arrays.asList(nums));
        return permutations;
    }

    // Recursive case: find all permutations of the remaining elements
    for (int i = 0; i < nums.length; i++) {
        int[] remaining = new int[nums.length - 1];
        System.arraycopy(nums, 0, remaining, 0, i);
        System.arraycopy(nums, i + 1, remaining, i, nums.length - i - 1);
        List<List<Integer>> permutationsOfRemaining = permute(remaining);

        // Insert the current element at all possible positions in each permutation of the remaining elements
        for (List<Integer> permutation : permutationsOfRemaining) {
            for (int j = 0; j <= permutation.size(); j++) {
                permutation.add(j, nums[i]);
            }
        }

        permutations.addAll(permutationsOfRemaining);
    }

    return permutations;
}

