public int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                maxLen = Math.max(maxLen, DFS(mat, i, j));
            }
        }
    }

    return maxLen;
}

int DFS(int[][] mat, int i, int j) {
    int m = mat.length;
    int n = mat[0].length;
    int len = 0;

    if (i < 0 || i >= m || j < 0 || j >= n || mat[i][j] == 0) {
        return 0;
    }

    len = 1 + DFS(mat, i + 1, j + 1) + DFS(mat, i - 1, j - 1) + DFS(mat, i + 1, j - 1) + DFS(mat, i - 1, j + 1);

    return len;
}

