public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    int maxArea = 0;
    for (int i = 1; i < n; i++) {
        int minIdx = i;
        for (int j = i - 1; j >= 0; j--) {
            if (heights[j] <= heights[i]) {
                minIdx = j;
                break;
            }
        }
        left[i] = minIdx;
    }

    for (int i = n - 2; i >= 0; i--) {
        int minIdx = i;
        for (int j = i + 1; j < n; j++) {
            if (heights[j] <= heights[i]) {
                minIdx = j;
                break;
            }
        }
        right[i] = minIdx;
    }

    for (int i = 0; i < n; i++) {
        int area = heights[i] * (right[i] - left[i] + 1);
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

